/** Regenerates supabase/seed.sql from lib/seed.ts (settings, menu, tables). Usage: npx tsx scripts/generate-seed-sql.ts */
import fs from "node:fs";
import path from "node:path";
import { DEFAULT_MENU, DEFAULT_SETTINGS, DEFAULT_TABLES } from "../lib/seed";

const q = (v: unknown) => (v === null || v === undefined ? "null" : `'${String(v).replace(/'/g, "''")}'`);
const arr = (a: string[]) => `array[${a.map(q).join(",")}]::text[]`;
const json = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  "-- DineLine AI · seed data (settings, menu, tables). Generated by scripts/generate-seed-sql.ts",
  "-- Run after schema.sql. Safe to re-run: existing rows are updated.",
  "",
  `insert into settings (id, data) values (1, ${json(DEFAULT_SETTINGS)})`,
  "  on conflict (id) do update set data = excluded.data, updated_at = now();",
  "",
  "insert into menu_items (id, name, category, description, price, sizes, add_ons, allergens, dietary, spicy, is_available, is_upsell, popular, sort_order) values",
  DEFAULT_MENU.map(
    (m, i) =>
      `  (${q(m.id)}, ${q(m.name)}, ${q(m.category)}, ${q(m.description)}, ${m.price.toFixed(2)}, ${json(m.sizes)}, ${json(m.addOns)}, ${arr(m.allergens)}, ${arr(m.dietary)}, ${m.spicy}, ${m.isAvailable}, ${m.isUpsell}, ${m.popular}, ${i})`,
  ).join(",\n"),
  "on conflict (id) do update set name = excluded.name, category = excluded.category, description = excluded.description, price = excluded.price,",
  "  sizes = excluded.sizes, add_ons = excluded.add_ons, allergens = excluded.allergens, dietary = excluded.dietary, spicy = excluded.spicy,",
  "  is_available = excluded.is_available, is_upsell = excluded.is_upsell, popular = excluded.popular, sort_order = excluded.sort_order;",
  "",
  "insert into dining_tables (id, number, seats, area) values",
  DEFAULT_TABLES.map((t) => `  (${q(t.id)}, ${t.number}, ${t.seats}, ${q(t.area)})`).join(",\n"),
  "on conflict (id) do update set number = excluded.number, seats = excluded.seats, area = excluded.area;",
  "",
];

fs.writeFileSync(path.join(process.cwd(), "supabase", "seed.sql"), lines.join("\n"));
console.log("Wrote supabase/seed.sql");
